<script lang="ts">
 import {api} from './lib/api';import {parseAccessKey,metadataKey} from './lib/metadata';
 let {connected,action='connect',history}:{connected:(capability?:Uint8Array<ArrayBuffer>,pin?:{community:string;tip:string})=>Promise<void>;action?:'connect'|'replica-copy';history?:()=>Promise<string[]>}=$props();
 let url=$state(''),key=$state(''),providerToken=$state(''),accessId=$state(''),secretKey=$state(''),needsProvider=$state(false),busy=$state(false),error=$state(''),previous=$state('');
 $effect(()=>{if(previous!==url){previous=url;key='';providerToken='';accessId='';secretKey='';needsProvider=false;}});
 async function open(){busy=true;error='';try{const capability=key.startsWith('nb2:')?parseAccessKey(key):undefined;const epoch=capability?(await import('./lib/crypto')).un64(capability.key):undefined;const metadata=epoch?await metadataKey(epoch):undefined;if(key&&!metadata&&!/^(gh[a-z]_|github_pat_|[0-9a-f]{40}$)/i.test(key))throw Error('A forum key starts with nb2:. Never enter a passphrase or an unlabelled decryption key as a provider token.');const token=providerToken||(!metadata?key:'');const {connection}=await api('/api/resolve',{url,provider_token:token,access_key:accessId,secret_key:secretKey,...(capability?{namespace:capability.namespace}:{})});
  if(capability){connection.community=capability.community;connection.branch_pin=capability.branch;connection.checkpoint=capability.checkpoint;}
  const access={backend:await import('./lib/crypto').then(async c=>c.b64(Uint8Array.from((await c.hash(c.canonical(connection.primary))).match(/../g)!,x=>parseInt(x,16)))),token,access_key:accessId,secret_key:secretKey};
  if(action==='replica-copy'){await api('/api/replica-copy',{backend:connection.primary,access,metadata_keys:history?await history():[]});await connected();return;}
  await api('/api/connect',{connection,access,...(metadata?{metadata_key:metadata}:{})});const status=await api('/api/status');if(!status.configured){if(!confirm('No forum exists at this storage location. Create a new encrypted forum here?'))return;if(!status.writable){needsProvider=true;throw Error('Creating a forum needs provider write permission. Add your scoped storage credential below.');}}
  key='';providerToken='';secretKey='';accessId='';await connected(epoch,capability?{community:capability.community,tip:'p:'+capability.checkpoint}:undefined);
 }catch(e){error=e instanceof Error?e.message:String(e);if(/private|denied|provider|credential|permission|bucket/i.test(error))needsProvider=true;}finally{busy=false;}}
</script>
<section class="card setup"><h1>{action==='connect'?'Open your forum.':'Add an encrypted backup.'}</h1><p>{action==='connect'?'Point NightBuoy at the storage directory. Your key unlocks the forum; names and membership stay encrypted.':'Choose an independent storage root. Only encrypted data is copied.'}</p><form onsubmit={e=>{e.preventDefault();open();}}><label>Storage URL<input type="url" bind:value={url} autocomplete="off" placeholder="https://github.com/owner/repository" required/></label><label>Access key (optional)<input type="password" bind:value={key} autocomplete="off" placeholder="Forum access key or scoped provider token"/></label>
{#if needsProvider}<div class="alert"><p>This storage provider requires authorization. Credentials go only to the API for the URL shown above and stay in companion memory.</p>{#if url.startsWith('s3:')||url.startsWith('s3+')}<label>Provider access key ID<input type="password" bind:value={accessId} autocomplete="off"/></label><label>Provider secret key<input type="password" bind:value={secretKey} autocomplete="off"/></label>{:else}<label>Scoped provider token<input type="password" bind:value={providerToken} autocomplete="off"/></label>{/if}</div>{/if}
{#if error}<p class="error" role="alert">{error}</p>{/if}<button class="primary" disabled={busy||!url}>{busy?'Connecting…':action==='connect'?'Join':'Copy encrypted backup'}</button></form></section>
